82	export const getMimeType = (blob: Blob | string): string => {
83	  let name: string;
84	  if (typeof blob === "string") {
85	    name = blob;
86	  } else {
87	    if (blob.type) {
88	      return blob.type;
89	    }
90	    name = blob.name || "";
91	  }
92	  if (/\.(excalidraw|json)$/.test(name)) {
93	    return MIME_TYPES.json;
94	  } else if (/\.png$/.test(name)) {
95	    return MIME_TYPES.png;
96	  } else if (/\.jpe?g$/.test(name)) {
97	    return MIME_TYPES.jpg;
98	  } else if (/\.svg$/.test(name)) {
99	    return MIME_TYPES.svg;
100	  } else if (/\.excalidrawlib$/.test(name)) {
101	    return MIME_TYPES.excalidrawlib;
102	  }
103	  return "";
104	};
