106	export const getFileHandleType = (handle: FileSystemFileHandle | null) => {
107	  if (!handle) {
108	    return null;
109	  }
110	
111	  return handle.name.match(/\.(json|excalidraw|png|svg)$/)?.[1] || null;
112	};
