131	export const isSupportedImageFile = (
132	  blob: Blob | null | undefined,
133	): blob is Blob & { type: ValueOf<typeof IMAGE_MIME_TYPES> } => {
134	  const { type } = blob || {};
135	  return isSupportedImageFileType(type);
136	};
