138	export const loadSceneOrLibraryFromBlob = async (
139	  blob: Blob | File,
140	  /** @see restore.localAppState */
141	  localAppState: AppState | null,
142	  localElements: readonly ExcalidrawElement[] | null,
143	  /** FileSystemFileHandle. Defaults to `blob.handle` if defined, otherwise null. */
144	  fileHandle?: FileSystemFileHandle | null,
145	) => {
146	  const contents = await parseFileContents(blob);
147	  let data;
148	  try {
149	    try {
150	      data = JSON.parse(contents);
151	    } catch (error: any) {
152	      if (isSupportedImageFile(blob)) {
153	        throw new ImageSceneDataError(
154	          "Image doesn't contain scene",
155	          "IMAGE_NOT_CONTAINS_SCENE_DATA",
156	        );
157	      }
158	      throw error;
159	    }
160	    if (isValidExcalidrawData(data)) {
161	      return {
162	        type: MIME_TYPES.excalidraw,
163	        data: {
164	          elements: restoreElements(data.elements, localElements, {
165	            repairBindings: true,
166	            deleteInvisibleElements: true,
167	          }),
168	          appState: restoreAppState(
169	            {
170	              theme: localAppState?.theme,
171	              fileHandle: fileHandle || blob.handle || null,
172	              ...cleanAppStateForExport(data.appState || {}),
173	              ...(localAppState
174	                ? calculateScrollCenter(data.elements || [], localAppState)
175	                : {}),
176	            },
177	            localAppState,
178	          ),
179	          files: data.files || {},
180	        },
181	      };
182	    } else if (isValidLibrary(data)) {
183	      return {
184	        type: MIME_TYPES.excalidrawlib,
185	        data,
186	      };
187	    }
188	    throw new Error("Error: invalid file");
189	  } catch (error: any) {
190	    if (error instanceof ImageSceneDataError) {
191	      throw error;
192	    }
193	    throw new Error("Error: invalid file");
194	  }
195	};
