197	export const loadFromBlob = async (
198	  blob: Blob,
199	  /** @see restore.localAppState */
200	  localAppState: AppState | null,
201	  localElements: readonly ExcalidrawElement[] | null,
202	  /** FileSystemFileHandle. Defaults to `blob.handle` if defined, otherwise null. */
203	  fileHandle?: FileSystemFileHandle | null,
204	) => {
205	  const ret = await loadSceneOrLibraryFromBlob(
206	    blob,
207	    localAppState,
208	    localElements,
209	    fileHandle,
210	  );
211	  if (ret.type !== MIME_TYPES.excalidraw) {
212	    throw new Error("Error: invalid file");
213	  }
214	  return ret.data;
215	};
